'use strict';
(function(){
const manifest=window.PoeticsStateUrbanManifest;if(!manifest)return;
const cache=new Map(),pending=new Map(),errors=new Set(),h=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const polys=g=>g.type==='MultiPolygon'?g.coordinates:[g.coordinates],merc=([x,y])=>[x,Math.log(Math.tan(Math.PI/4+y*Math.PI/360))*180/Math.PI];
function validate(state,d){if(d.state!==state||!d.geometry||!Array.isArray(d.cities)||d.metadata?.stateUploadSha256!==manifest.metadata.stateUploadSha256)throw Error('Unexpected state layer');for(const g of [d.geometry,...d.cities.map(c=>c.geometry)]){if(!['Polygon','MultiPolygon'].includes(g.type))throw Error('Invalid geometry');for(const poly of polys(g))for(const r of poly){if(r.length<4||JSON.stringify(r[0])!==JSON.stringify(r.at(-1)))throw Error('Open ring');for(const p of r)if(p.length!==2||!p.every(Number.isFinite)||Math.abs(p[0])>180||Math.abs(p[1])>90)throw Error('Invalid coordinate');}}if(JSON.stringify(d.cities.map(c=>c.city))!==JSON.stringify(manifest.states[state].cities))throw Error('City manifest mismatch');return d;}
function prime(state,data){validate(state,data);cache.set(state,data);errors.delete(state);return data;}
function ensure(state,done){if(cache.has(state)||pending.has(state)||errors.has(state)||!manifest.states[state]||typeof window.fetch!=='function')return;const p=window.fetch(manifest.states[state].url).then(r=>{if(!r.ok)throw Error('State layer unavailable');return r.json();}).then(d=>prime(state,d)).catch(()=>errors.add(state)).finally(()=>{pending.delete(state);done();});pending.set(state,p);return p;}
function projection(g){const points=polys(g).flat(2).map(merc),xs=points.map(p=>p[0]),ys=points.map(p=>p[1]),b=[Math.min(...xs),Math.min(...ys),Math.max(...xs),Math.max(...ys)],scale=Math.min(610/(b[2]-b[0]),465/(b[3]-b[1])),cx=(b[0]+b[2])/2,cy=(b[1]+b[3])/2;return p=>{const [x,y]=merc(p);return [372+(x-cx)*scale,320-(y-cy)*scale];};}
function path(g,project){return polys(g).map(poly=>poly.map(r=>r.map((p,i)=>{const [x,y]=project(p);return(i?'L':'M')+x.toFixed(2)+' '+y.toFixed(2);}).join(' ')+'Z').join(' ')).join(' ');}
function render(state,counts,values,selected='All places',maximum=0){const d=cache.get(state);if(!d)return `<div class="urban-layer-status" role="status"><h3>${h(state)}</h3><p>${errors.has(state)?'The state map could not load. Refresh this page to try again.':'Loading the state map…'}</p></div>`;const m=window.PoeticsStateMap,focused=d.cities.find(c=>c.city===selected&&(counts[c.city]||0)>0),project=projection(focused?.geometry||d.geometry),total=Object.values(values||{}).reduce((a,b)=>a+b,0),band=m.frequencyBand(total,maximum),outline=path(d.geometry,project),parts=m.categories.filter(c=>values?.[c]>0),start=372-(parts.length-1)*27;
const badges=parts.map((c,i)=>`<g role="button" tabindex="0" data-category-state="${h(state)}" data-category-count="${h(c)}" data-count="${values[c]}" aria-label="${h(state)}: ${values[c]} ${h(c)} entries" transform="translate(${start+i*54},48)"><circle r="19" fill="${m.colors[c]}" stroke="#fffaf3" stroke-width="1"/><text text-anchor="middle" y="5" fill="${['People','Publications'].includes(c)?'#fffaf3':'#171717'}">${values[c]}</text></g>`).join('');
const urban=d.cities.map(c=>`<path class="urban-extent ${selected===c.city?'selected':''}" d="${path(c.geometry,project)}" fill-rule="evenodd" ${(counts[c.city]||0)>0?`data-map-city="${h(c.city)}" role="button" tabindex="0"`:'aria-disabled="true"'} aria-label="${h(c.city)}: ${counts[c.city]||0} matching entries; urban area ${h(c.sourceName)},2020"><title>${h(c.city)} · ${h(c.sourceName)} · Urban extent2020${c.note?' · '+h(c.note):''}</title></path>`).join('');
const labels=d.cities.map(c=>{const [x,y]=project(c.labelPoint);return `<g class="urban-city-label ${selected===c.city?'selected':''}" ${(counts[c.city]||0)>0?`data-map-city="${h(c.city)}" role="button" tabindex="0"`:'aria-disabled="true"'} aria-label="Select ${h(c.city)}, ${counts[c.city]||0} matching entries" transform="translate(${x.toFixed(2)},${y.toFixed(2)})"><circle r="19" class="city-hit"/><circle r="3" class="city-centre-dot"/><text x="8" y="-5">${h(c.city)}</text><text x="8" y="9" class="urban-city-count">${counts[c.city]||0} entries</text></g>`;}).join('');
const back=focused?`<button data-map-city="All places" class="urban-back-state">Back to ${h(state)}</button>`:'';
const notes=d.cities.filter(c=>c.note||c.crossState).map(c=>`${h(c.city)}: ${h(c.note||'urban area crosses the state boundary')}${c.crossState?' · clipped to selected state':''}.`).join(' ');
return `${back}<svg data-map-level="${focused?'urban':'state'}" class="nigeria-gis state-urban-gis" viewBox="0 0 744 600" role="group" aria-label="${h(state)} state map with urban extents2020"><defs><clipPath id="state-urban-clip"><path d="${outline}" clip-rule="evenodd"/></clipPath></defs><text x="372" y="17" text-anchor="middle" class="state-city-heading">${h(focused?focused.city+' · '+state:state)} · ${focused?counts[focused.city]:total} matching entries</text>${badges}<path class="osm-state-outline" d="${outline}" fill="${band.fill}" fill-rule="evenodd"/><g clip-path="url(#state-urban-clip)">${urban}${labels}</g></svg><p class="state-city-source"><span class="urban-extent-key" aria-hidden="true"></span> Urban extent ·2020 · <a href="${h(manifest.metadata.urbanSource)}" target="_blank" rel="noopener">Africapolis / OECD-SWAC &amp; e-Geopolis</a> · CC BY4. Settlement footprints, not legal city limits. Display clipped to the selected state. <a href="${h(manifest.metadata.source)}" target="_blank" rel="noopener">States: GRID3 / geoBoundaries ·2022 · CC BY4</a>.${d.cities.length?'':' No matched Atlas city footprint in this state yet.'}${d.unmatched.length?' Urban extent unresolved: '+h(d.unmatched.join(', '))+'. Use the city filter to browse entries.':''}${notes?' '+notes:''}</p>`;
}
window.PoeticsStateUrbanMap={has:state=>!!manifest.states[state],citiesForState:state=>manifest.states[state]?.cities||[],ensure,render,prime,validate,projection,path,loaded:state=>cache.has(state),manifest};
})();
